#define YUNET_DIAG_COMPARE(label, got, ref, count) do { \
  uint32_t _bad=0, _first=UINT32_MAX; float _max=0.0f, _sum=0.0f; \
  uint32_t _imax=0; \
  for (uint32_t _i=0; _i<(uint32_t)(count); ++_i) { \
    float _d=fabsf((got)[_i]-(ref)[_i]); _sum += _d; \
    if (_d>_max) { _max=_d; _imax=_i; } \
    if (!isfinite((got)[_i]) || !isfinite((ref)[_i]) || _d>0.0001f) { \
      if (_first==UINT32_MAX) _first=_i; ++_bad; \
    } \
  } \
  printf("[YUNET_DIAG] %s n=%u bad=%u max=%.9g max_i=%u mean=%.9g first=%u\\n", \
    label, (uint32_t)(count), _bad, _max, _imax, _sum/(float)(count), _first); \
} while(0)
